-- Every rank's spell id back to its tree and talent, because a profile names a
-- talent by the spell of the rank that was taken.
ns.TALENT_TBC_BY_SPELL = {}
for class, trees in pairs(ns.TALENT_TREES_TBC) do
	for treeIndex, tree in ipairs(trees) do
		for talentIndex, talent in ipairs(tree.talents) do
			for rank, spellID in ipairs(talent[3]) do
				ns.TALENT_TBC_BY_SPELL[spellID] = { class, treeIndex, talentIndex, rank }
			end
		end
	end
end
